<?php
 namespace Pterodactyl\Services\Dezerx\FiveM; use Pterodactyl\Services\Dezerx\ServerVariables; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class ServerConfig { public const MARKER_SUFFIX = 'fivem'; public const TXADMIN_PORT = 40120; public const ENABLE_VARIABLE = 'TXADMIN_ENABLE'; public const PORT_VARIABLES = ['TXHOST_TXA_PORT', 'TXADMIN_PORT']; public const GAME_BUILDS = [ '1604', '2060', '2189', '2372', '2545', '2612', '2699', '2802', '2944', '3095', '3258', '3323', '3407', '3570', ]; public static function candidates(ServerFiles $files): array { $paths = ['server.cfg']; foreach ($files->listFiles('/txData') ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if ($name !== '') { $paths[] = 'txData/' . $name . '/server.cfg'; } } return $paths; } public static function locate(ServerFiles $files): ?array { foreach (self::candidates($files) as $path) { $contents = $files->fileContents($path, 512_000); if ($contents !== null) { return ['path' => $path, 'contents' => $contents]; } } return null; } public static function gameBuild(string $config): ?string { return preg_match('/^\s*(?:set[a-z]*\s+)?sv_enforceGameBuild\s+"?(\d+)"?/mi', $config, $found) === 1 ? $found[1] : null; } public static function withGameBuild(string $config, string $build): string { $pattern = '/^[ \t]*(?:set[a-z]*[ \t]+)?sv_enforceGameBuild[ \t]+"?\d+"?[ \t]*$/mi'; if ($build === '') { return preg_replace($pattern, '', $config) ?? $config; } $line = 'sv_enforceGameBuild ' . $build; if (preg_match($pattern, $config) === 1) { return preg_replace($pattern, $line, $config, 1) ?? $config; } return rtrim($config, "\n") . "\n\n" . $line . "\n"; } public static function txAdminPort(string $config): ?int { if (preg_match('/txAdminPort[ \t]+"?(\d{2,5})"?/i', $config, $found) === 1) { return (int) $found[1]; } return null; } public static function txAdmin(ServerFiles $files, ?string $config): array { $server = $files->server; $toggle = ServerVariables::definition($server, self::ENABLE_VARIABLE); $portVariable = ServerVariables::firstDefinition($server, self::PORT_VARIABLES); $fromEgg = $portVariable === null ? null : self::port(ServerVariables::valueOf($portVariable)); $fromConfig = $config === null ? null : self::txAdminPort($config); $port = $fromEgg ?? $fromConfig ?? self::TXADMIN_PORT; $source = $fromEgg !== null ? 'variable' : ($fromConfig !== null ? 'config' : 'default'); $url = null; foreach ($files->allocations() as $allocation) { if ((int) ($allocation['port'] ?? 0) === $port) { $url = 'http://' . $allocation['ip'] . ':' . $port; break; } } return [ 'url' => $url, 'port' => $port, 'portSource' => $source, 'portVariable' => $portVariable?->env_variable, 'configured' => $source !== 'default', 'supported' => $toggle !== null, 'variable' => $toggle?->env_variable, 'editable' => $toggle !== null && (bool) $toggle->user_editable, 'enabled' => $toggle === null ? null : filter_var(ServerVariables::valueOf($toggle), FILTER_VALIDATE_BOOL), ]; } private static function port(string $value): ?int { $port = (int) trim($value); return $port > 0 && $port <= 65535 ? $port : null; } public static function installedBuild(ServerFiles $files): ?string { $marker = \Pterodactyl\Services\Dezerx\Brand::read($files, '/', self::MARKER_SUFFIX, 64); if ($marker === null) { return null; } return preg_match('/(\d{3,7})/', $marker, $found) === 1 ? $found[1] : null; } } 